"use client";

// Runs the Liquid Glass bento designed on the canvas. The markup and the component logic come
// straight from the artboard (template.js, generated by build_site.py); this file is the small
// runtime around it: state -> render -> morph the DOM in place, so CSS transitions and scroll
// positions survive every update.
import { useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import morphdom from "./morphdom";
import { CSS, FONTS, LOGIC, PROPS, render } from "./template";

type Vals = Record<string, unknown>;
type Fn = (e: unknown) => void;

const esc = (x: unknown) =>
  x == null || typeof x === "object" || typeof x === "function" ? "" : String(x).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/"/g, "&quot;");
const get = (o: Vals, path: string): unknown => path.split(".").reduce<unknown>((a, k) => (a == null ? undefined : (a as Vals)[k]), o);

export default function Bento() {
  const host = useRef<HTMLDivElement>(null);
  const router = useRouter();

  useEffect(() => {
    const el = host.current;
    if (!el) return;
    let vals: Vals = {};
    let drawing = false;
    let again = false;

    const root = document.documentElement;
    root.classList.remove("to-bento");

    class DCLogic {
      props: Vals;
      state: Vals | null = null;
      constructor(p: Vals) { this.props = p; }
      setState(o: Vals) { this.state = { ...(this.state || {}), ...o }; draw(); }
      forceUpdate() { draw(); }
    }
    // eslint-disable-next-line @typescript-eslint/no-implied-eval
    const Component = new Function("DCLogic", `${LOGIC}\nreturn Component;`)(DCLogic) as new (p: Vals) => DCLogic & { renderVals(): Vals; componentDidMount?(): void; componentWillUnmount?(): void };

    const leave = () => {
      const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      el.classList.remove("bento-enter");
      el.classList.add("bento-leave");
      try { sessionStorage.setItem("yj-from-bento", "1"); } catch {}
      window.setTimeout(() => router.push("/"), reduce ? 0 : 430);
    };
    const onTheme = (t: string) => {
      root.dataset.theme = t;
      try { localStorage.setItem("yj-theme", t); } catch {}
    };

    const inst = new Component({ ...PROPS, startTheme: root.dataset.theme === "light" ? "light" : "dark", onClassic: leave, onTheme });

    function draw() {
      if (drawing) { again = true; return; }
      drawing = true;
      do {
        again = false;
        vals = inst.renderVals();
        morphdom(el!, `<div>${render(vals, esc)}</div>`, { childrenOnly: true });
      } while (again);
      drawing = false;
      // the open sheet owns scrolling; the page behind stays put
      root.style.overflow = vals.isOpen ? "hidden" : "";
    }

    const call = (attr: string, target: Element, ev: Event) => {
      const name = target.getAttribute(attr);
      const fn = name ? (get(vals, name) as Fn | undefined) : undefined;
      if (typeof fn === "function") fn({ currentTarget: target, target: ev.target, preventDefault: () => ev.preventDefault() });
    };
    const onClick = (e: Event) => {
      const t = e.target instanceof Element ? e.target.closest("[data-click]") : null;
      if (!t || !el.contains(t)) return;
      if (t.tagName === "A") { e.preventDefault(); e.stopPropagation(); }
      call("data-click", t, e);
    };
    const onScroll = (e: Event) => {
      const t = e.target as Element;
      if (t instanceof Element && t.hasAttribute("data-scroll")) call("data-scroll", t, e);
    };
    const onInput = (e: Event) => {
      const t = e.target as Element;
      if (t instanceof Element && t.hasAttribute("data-change")) call("data-change", t, e);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape" && vals.isOpen && typeof vals.close === "function") (vals.close as Fn)(null);
    };

    el.addEventListener("click", onClick);
    el.addEventListener("scroll", onScroll, true);
    el.addEventListener("input", onInput);
    window.addEventListener("keydown", onKey);

    draw();
    el.classList.add("bento-enter");
    const settle = window.setTimeout(() => el.classList.remove("bento-enter"), 1500);
    inst.componentDidMount?.();

    return () => {
      inst.componentWillUnmount?.();
      window.clearTimeout(settle);
      el.removeEventListener("click", onClick);
      el.removeEventListener("scroll", onScroll, true);
      el.removeEventListener("input", onInput);
      window.removeEventListener("keydown", onKey);
      root.style.overflow = "";
    };
  }, [router]);

  return (
    <>
      <link rel="stylesheet" href={FONTS} precedence="default" />
      <style dangerouslySetInnerHTML={{ __html: CSS }} />
      <div ref={host} className="bento-host" />
    </>
  );
}
